/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import page2020.view.Content;import page2020.view.Element;public class H5text extends Element<H5text, Content<?>> {	public static final class T {		public static final String h1 = "h1";		public static final String h2 = "h2";		public static final String h3 = "h3";		public static final String h4 = "h4";		public static final String h5 = "h5";		public static final String h6 = "h6";		public static final String abbr = "abbr";		public static final String b = "b";		public static final String cite = "cite";		public static final String code = "code";		public static final String del = "del";		public static final String dfn = "dfn";		public static final String em = "em";		public static final String ins = "ins";		public static final String kbd = "kbd";		public static final String mark = "mark";		public static final String pre = "pre";		public static final String q = "q";		public static final String samp = "samp";		public static final String small = "small";		public static final String strong = "strong";		public static final String sub = "sub";		public static final String sup = "sup";		public static final String u = "u";		public static final String var = "var";	}	public H5text(String tagName) {		switch (tagName) {		case T.h1:		case T.h2:		case T.h3:		case T.h4:		case T.h5:		case T.h6:					case T.abbr:		case T.b:		case T.cite:		case T.code:		case T.del:		case T.dfn:		case T.em:		case T.ins:		case T.kbd:		case T.mark:		case T.pre:		case T.q:		case T.samp:		case T.small:		case T.strong:		case T.sub:		case T.sup:		case T.u:		case T.var:			super.setTagName(tagName);			break;		default:			super.setTagName("span");			break;		}	}}